#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
VERCEL_PROJECT_DIR="${VERCEL_PROJECT_DIR:-/Users/faraz/Documents/GitHub/nicc-business}"
SUPA="https://supabase.com/dashboard/project/jmqljbqvyhwdrxugbwun"
SITE="https://nicc-business.vercel.app"
MIG_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/supabase/migrations"

# clip "text" copies to the clipboard when a tool exists (so secrets never
# have to be printed on screen). Returns non-zero if there is none.
clip() {
  if   command -v pbcopy  >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v xclip   >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  elif command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe
  else return 1; fi
}

# clip_file FILE copies a file's contents to the clipboard.
clip_file() { clip "$(cat "$1")"; }

# vercel_env NAME VALUE sets a production env var, replacing any old value.
vercel_env() {
  local name="$1" value="$2"
  if ! command -v vercel >/dev/null 2>&1; then
    SKIPPED+=("Vercel env $name (CLI missing): Project Settings > Environment Variables > add $name for Production")
    warn "vercel CLI not found; add $name in the Vercel dashboard instead"
    return
  fi
  (cd "$VERCEL_PROJECT_DIR" && vercel env rm "$name" production -y >/dev/null 2>&1 || true)
  if (cd "$VERCEL_PROJECT_DIR" && printf '%s' "$value" | vercel env add "$name" production >/dev/null 2>&1); then
    printf '  %s✓ set%s Vercel env %s (production)\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("Vercel env $name: cd $VERCEL_PROJECT_DIR && vercel env add $name production")
    warn "couldn't set $name automatically; see the summary at the end"
  fi
}

banner "NICC Business: lock down forms, captcha and email alerts"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Ship the code"
say "Everything below needs the new /api routes to be live."
step "Open a pull request for branch claude/noor-website-review-e817fe,"
step "merge it into main, and wait for Vercel to finish deploying."
note "(Vercel deploys main automatically. Check the Deployments tab.)"
open_url "https://vercel.com/dashboard"
confirm "Is the new version live on $SITE?" || { warn "Come back and re-run once it is."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Database changes (hardening migration)"
say "Safe to run more than once. It stops owners awarding themselves badges,"
say "sends edited listings back for review, blocks self-reviews, and adds the"
say "newsletter and saved-listings tables."
if clip_file "$MIG_DIR/2026-10-04-hardening.sql"; then
  note "The SQL is already on your clipboard."
else
  note "Copy it from: $MIG_DIR/2026-10-04-hardening.sql"
fi
open_url "$SUPA/sql/new"
step "Paste into the SQL editor and click Run."
step "Expect 'Success. No rows returned'. If you see an error, stop and send it to Claude."
confirm "Did it run successfully?" || { warn "Fix that first; the later stages depend on it."; exit 0; }

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Give the server the Supabase service key"
say "/api/submit needs this SECRET key to save contact messages after it has"
say "verified Turnstile. Never put it in the page code."
open_url "$SUPA/settings/api-keys"
step "Under 'Secret keys' (or the 'Legacy' tab: 'service_role'), click Reveal and copy it."
note "Menu names move around; any key labelled secret / service_role works."
ask_secret SUPABASE_SERVICE_ROLE_KEY "Paste the secret key (hidden):"
[[ -n "${SUPABASE_SERVICE_ROLE_KEY:-}" ]] || { warn "No key entered."; exit 1; }
write_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"
vercel_env SUPABASE_SERVICE_ROLE_KEY "$SUPABASE_SERVICE_ROLE_KEY"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Redeploy and send a test message"
say "New env vars only apply after a redeploy."
open_url "https://vercel.com/dashboard"
step "Open the nicc-business project > Deployments > latest > ⋯ > Redeploy."
pause "Wait until it says Ready, then press Enter."
open_url "$SITE/noor-business.html#/contact"
step "Send a real test message through the Contact form."
step "Complete the Turnstile box first."
open_url "$SUPA/editor"
step "In the Table Editor, open contact_messages and confirm your message is there."
confirm "Is the test message in the table?" || { warn "Do NOT continue. The next stage would break the form. Send logs/errors to Claude."; exit 0; }

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Close the direct-insert hole"
say "After this, the ONLY way into contact_messages is /api/submit."
if clip_file "$MIG_DIR/2026-10-04-lock-public-inserts.sql"; then
  note "The SQL is already on your clipboard."
else
  note "Copy it from: $MIG_DIR/2026-10-04-lock-public-inserts.sql"
fi
open_url "$SUPA/sql/new"
step "Paste and Run."
confirm "Ran successfully?" || { warn "Re-run when ready."; exit 0; }
step "Now send one MORE test message from the Contact page."
confirm "Did it still go through?" || warn "If not, send the error to Claude. Your quickest rollback is re-adding the old insert policy."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Turn on Turnstile for sign-ups"
say "This makes Supabase itself reject bot sign-ups (the browser check alone"
say "can be skipped by calling Supabase directly)."
TS_SECRET=$(_existing TURNSTILE_SECRET_KEY || true)
if [[ -n "$TS_SECRET" ]] && clip "$TS_SECRET"; then
  note "Your Turnstile SECRET key is on the clipboard (not shown here)."
else
  step "Get it at: Cloudflare dashboard > Turnstile > your widget > Secret key"
  open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
fi
open_url "$SUPA/auth/protection"
step "Authentication > Attack Protection: switch on 'Enable Captcha protection'."
step "Provider: Cloudflare Turnstile. Paste the secret key. Save."
confirm "Saved?" || { warn "Re-run this stage when ready; do NOT set SUPABASE_AUTH_CAPTCHA before it."; exit 0; }
vercel_env SUPABASE_AUTH_CAPTCHA "1"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Email alerts: Resend + secrets"
say "Volunteers get an email whenever a listing, claim, review or contact"
say "message arrives. Resend has a free tier."
open_url "https://resend.com/api-keys"
step "Create an account/log in. Add and verify a sending domain (Domains page)"
note "or use onboarding@resend.dev as the sender for a quick test."
step "API Keys > Create API key (sending access). Copy it."
ask_secret RESEND_API_KEY "Paste the Resend API key (hidden):"
ask NOTIFY_EMAIL_TO "Who receives alerts? (comma-separated emails):"
ask NOTIFY_EMAIL_FROM "Sender address (e.g. NICC Business <alerts@yourdomain.org>):"
NOTIFY_SECRET=$(_existing NOTIFY_SECRET || true)
[[ -n "$NOTIFY_SECRET" ]] || NOTIFY_SECRET=$(openssl rand -hex 24)
write_env RESEND_API_KEY "$RESEND_API_KEY"
write_env NOTIFY_EMAIL_TO "$NOTIFY_EMAIL_TO"
write_env NOTIFY_EMAIL_FROM "$NOTIFY_EMAIL_FROM"
write_env NOTIFY_SECRET "$NOTIFY_SECRET"
vercel_env RESEND_API_KEY "$RESEND_API_KEY"
vercel_env NOTIFY_EMAIL_TO "$NOTIFY_EMAIL_TO"
vercel_env NOTIFY_EMAIL_FROM "$NOTIFY_EMAIL_FROM"
vercel_env NOTIFY_SECRET "$NOTIFY_SECRET"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Redeploy again"
say "SUPABASE_AUTH_CAPTCHA and the email settings only apply after a redeploy."
open_url "https://vercel.com/dashboard"
step "nicc-business > Deployments > latest > ⋯ > Redeploy."
pause "Press Enter once it says Ready."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Supabase webhooks (one per table)"
say "Create FOUR webhooks, identical except for the table:"
note "  businesses · claims · reviews · contact_messages"
if clip "Bearer $NOTIFY_SECRET"; then
  note "The Authorization header value ('Bearer …') is on your clipboard."
else
  note "Authorization header value: Bearer <NOTIFY_SECRET from $ENV_FILE>"
fi
open_url "$SUPA/integrations/webhooks/overview"
step "Database Webhooks > Create a new hook."
step "Name: notify-<table>   Table: <table>   Events: Insert only"
step "Type: HTTP Request   Method: POST   URL: $SITE/api/notify"
step "HTTP Headers: remove the defaults you don't need; add"
step "  Authorization = (paste from clipboard) and Content-Type = application/json"
step "Confirm. Repeat for each of the four tables."
pause "All four created? Press Enter."
say ""
step "Test: send a Contact-page message. The alert email should arrive in a minute."
confirm "Did the alert email arrive?" || SKIPPED+=("Alert email test failed: check Vercel function logs for /api/notify and the webhook delivery log in Supabase")

finish
